import sys
from pathlib import Path
ROOT=Path(__file__).absolute().parents[1]
sys.path.insert(0,str(ROOT/'tests'))
case=sys.argv.pop(2)
BODIES={'changed-png': "try:\n    wait(lambda:model.imagePreview._backend is not None,'backend');result['backend']=model.imagePreview._backend\n    assert model.openMedia(QUrl.fromLocalFile(str(source/'ordinary.png')))\n    wait(lambda:model.sourceKind=='still' and not model.imagePreview.busy,'source')\n    path=convert('still','png','changed-before-first-open')\n    active=model.activeMediaId;count=len(model.mediaItems);frame=model.playback._image_prepared\n    original_output_sha256=hashlib.sha256(path.read_bytes()).hexdigest()\n    replacement=QImage(128,96,QImage.Format_RGB32);replacement.fill(QColor(5,10,240));assert replacement.save(str(path));del replacement\n    changed_output_sha256=hashlib.sha256(path.read_bytes()).hexdigest();assert original_output_sha256!=changed_output_sha256\n    open_result();wait(lambda:not model.imagePreview.busy,'changed result settles')\n    wait(lambda:model.playback._image_ready,'picture ready')\n    viewer=find('viewerVideoOutput');grab=window.grabWindow();point=viewer.mapToScene(QPointF(viewer.width()/2,viewer.height()/2))\n    color=grab.pixelColor(round(point.x()*window.devicePixelRatio()),round(point.y()*window.devicePixelRatio())).getRgb()\n    assert grab.scaledToWidth(640).save(str(root/'changed-result-viewer.png'))\n    preserved=all(hashlib.sha256(Path(p).read_bytes()).hexdigest()==h for p,h in hashes.items())\n    result['changed_before_first_open']=dict(path=str(path),exported_sha256=original_output_sha256,changed_sha256=changed_output_sha256,\n        active_before=active,active_after=model.activeMediaId,tray_before=count,tray_after=len(model.mediaItems),\n        picture_preserved=model.playback._image_prepared is frame,painted_rgba=color,status=model.imagePreview.status,source_bytes_preserved=preserved)\n    print(json.dumps(result['changed_before_first_open'],indent=2),flush=True)\n    assert preserved\n    assert model.activeMediaId==active and len(model.mediaItems)==count and model.playback._image_prepared is frame,'Changed completed output was activated as the exported result'\n    result['passed']=True\n", 'corrupt-video': "try:\n    import subprocess\n    from mediaforge.infrastructure.ffmpeg.runtime import resolve_ffmpeg_runtime\n    wait(lambda:model.imagePreview._backend is not None,'backend');result['backend']=model.imagePreview._backend\n    assert model.openMedia(QUrl.fromLocalFile(str(source/'picture_0101.png')));wait(lambda:bool(model.sequenceConfirmation))\n    dialog=window.findChild(QObject,'sequenceConfirmationDialog');editor=dialog.findChild(QObject,'sequenceFpsConfirmation')\n    editor.setProperty('editText','30000/1001');click(find('confirmSequenceButton'))\n    wait(lambda:model.sourceKind=='sequence' and not model.imagePreview.busy,'source sequence')\n    path=convert('media','mp4','corrupt-video')\n    active=model.activeMediaId;count=len(model.mediaItems);frame=model.playback._image_prepared\n    before=hashlib.sha256(path.read_bytes()).hexdigest();raw=bytearray(path.read_bytes());marker=raw.index(b'mdat');size=int.from_bytes(raw[marker-4:marker],'big')\n    assert size>8 and marker-4+size<=len(raw)\n    raw[marker+4:marker-4+size]=bytes(size-8);path.write_bytes(raw)\n    runtime=resolve_ffmpeg_runtime();oracle=subprocess.run([str(runtime.ffmpeg),'-v','error','-xerror','-i',str(path),'-map','0:v:0','-f','null','-'],capture_output=True,timeout=10)\n    assert oracle.returncode!=0,'Corruption fixture unexpectedly decodes'\n    open_result();wait(lambda:model.canOpen,'video metadata worker finished')\n    loop=QEventLoop();QTimer.singleShot(200,loop.quit);loop.exec()\n    preserved=all(hashlib.sha256(Path(p).read_bytes()).hexdigest()==h for p,h in hashes.items())\n    result['corrupt_video']=dict(path=str(path),exported_sha256=before,corrupt_sha256=hashlib.sha256(path.read_bytes()).hexdigest(),\n        decoder_exit=oracle.returncode,decoder_error=oracle.stderr.decode('utf-8','replace')[:1200],active_before=active,active_after=model.activeMediaId,\n        tray_before=count,tray_after=len(model.mediaItems),source_kind=model.sourceKind,image_mode=model.playback.imageMode,\n        picture_preserved=model.playback._image_prepared is frame,public_frame_valid=model.playback._presentation_sink.videoFrame().isValid(),\n        error=model.errorMessage,source_bytes_preserved=preserved)\n    assert window.grabWindow().scaledToWidth(640).save(str(root/'corrupt-video-viewer.png'))\n    print(json.dumps(result['corrupt_video'],indent=2),flush=True);assert preserved\n    assert model.activeMediaId==active and len(model.mediaItems)==count and model.playback._image_prepared is frame,'Corrupt video result replaced the previous Viewer/Tray source'\n    result['passed']=True\n", 'existing-video-owner': "try:\n    from mediaforge.infrastructure.ffmpeg.runtime import resolve_ffmpeg_runtime\n    import subprocess\n    wait(lambda:model.imagePreview._backend is not None,'backend');result['backend']=model.imagePreview._backend\n    assert model.openMedia(QUrl.fromLocalFile(str(source/'picture_0101.png')));wait(lambda:bool(model.sequenceConfirmation))\n    dialog=window.findChild(QObject,'sequenceConfirmationDialog');editor=dialog.findChild(QObject,'sequenceFpsConfirmation')\n    editor.setProperty('editText','30000/1001');click(find('confirmSequenceButton'))\n    wait(lambda:model.sourceKind=='sequence' and not model.imagePreview.busy)\n    movie=convert('media','mp4','valid-source-video');open_result()\n    wait(lambda:model.sourceKind=='video' and model.playback.framesReliable and model.canOpen,'valid video')\n    active=model.activeMediaId;player=model.playback._player;sink=model.playback._presentation_sink;frame=sink.videoFrame()\n    movie_hash=hashlib.sha256(movie.read_bytes()).hexdigest()\n    candidate=convert('media','mp4','bad-candidate')\n    raw=bytearray(candidate.read_bytes());marker=raw.index(b'mdat');size=int.from_bytes(raw[marker-4:marker],'big');raw[marker+4:marker-4+size]=bytes(size-8);candidate.write_bytes(raw)\n    runtime=resolve_ffmpeg_runtime();oracle=subprocess.run([str(runtime.ffmpeg),'-v','error','-xerror','-i',str(candidate),'-map','0:v:0','-f','null','-'],capture_output=True,timeout=10)\n    assert oracle.returncode!=0\n    open_result();wait(lambda:model.canOpen,'candidate refusal')\n    assert model.activeMediaId==active and model.playback._player is player and not model.playback.imageMode\n    assert model.playback._presentation_sink is sink and sink.videoFrame().isValid() and model.errorMessage\n    assert hashlib.sha256(movie.read_bytes()).hexdigest()==movie_hash\n    assert all(hashlib.sha256(Path(p).read_bytes()).hexdigest()==h for p,h in hashes.items())\n    result.update(passed=True,player_preserved=True,active_preserved=True,public_frame_valid=True,error=model.errorMessage,decoder_exit=oracle.returncode,source_bytes_preserved=True)\n"}

code=(ROOT/'tests/native_exported_result.py').read_text(encoding='utf-8')
start=code.index("try:\n    wait(lambda:model.imagePreview._backend")
end=code.index('\nexcept BaseException:',start)
exec(compile(code[:start]+BODIES[case]+code[end:],str(ROOT/'tests/native_exported_result.py')+' [FC-01 '+case+']','exec'))
